INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(254,13,'pilihan_ganda','<ol><li>Al Qur`an adalah Kalam Allah yang diturunkan kepada Nabi Muhammad saw, tertulis dalam mushaf&nbsp; berbahasa Arab, yang disampaikan kepada kita dengan jalan&nbsp;mutawatir,&nbsp;dan membacanya mengandung nilai ibadah, dimulai dengan surah&nbsp;al Fatihah &nbsp;dan diakhiri dengan surah&nbsp;An Nas.</li></ol><p>Sebagaimana telah dimaklumi, bahwa Al Qur`an disamping sebagai kitab sucinya ummat Islam juga merupakan sumber hukum Islam yang pertama dan utama. Sebagai kitab suci, Al Qur`an harus diimani dan diaplikasikan dalam kehidupan sehari-hari, baik sebagai pribadi, sebagai anggota keluarga dalam sebuah rumah tangga maupun sebagai warga masyarakat, bangsa dan negara Republik Indonesia tercinta.</p><p>Dua pernyataan yang sesuai dengan kedudukan Al-Qur’an adalah….</p>',1,1,NULL,NULL,3,'["Al qur’an kalam allah Swt.","Sumber hukum pertama dan utama","Al qur’an di jadikan azimat","Mempelajari al qur’an dan mencari kelemahannya"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(255,13,'pilihan_ganda','<p>      </p><ol><li><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237080/ujian-madrasah/media/njjncmrnqhgh3xmfdwv2.png"></li></ol><p>Berdasarkan ayat diatas sikap yang sesuai dengan kandungan ayat tersebut adalah….</p>',2,1,NULL,NULL,3,'["kemapanan hidup","kekayaan yang takterduga","kecintaan yang mendalam kepada allah","pikiran yang bebas"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(256,13,'pilihan_ganda','<ol><li>Rahmat Allah Swt adalah kebaikan-kebaikan darinya sifat rahmat Allah pada hadis dibawah ini adalah….</li></ol><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237081/ujian-madrasah/media/xpojqmrypnfulgc86cp1.png"></p>',3,1,NULL,NULL,3,'["Rahmat allah ditunjukkan kepada manusia","Rahmat allah hanya untuk perorangan","Rahmat allah unuk orang yang beriman","Rahmat allah mendahului murkanya"]','"D"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(257,13,'pilihan_ganda','<div>Kandungan yang tepat pada qur’an surah al lail ayat 5,6 dan 7 pada pernyataan di bawah ini adalah</div>',4,1,NULL,NULL,3,'["Allah SWT bersumpah dengan menyebutkan gelapnya malam,terangnya siang,serta terciptanya laki-laki dan perempuan","Allah akan memberikan kemudahan bagi orang yang bertaqwa dan mau menginfakkan hartanya di jalannya.","Allah akan mengampuni semua hambanya,asalkan hamba tersebut bertaubat dengan taubatan nasuha","Allah akan menguji hambanya sesuai kemampuannya"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(258,13,'pilihan_ganda','<ol><li>Perhatikan hadis dibawah ini!</li></ol><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237082/ujian-madrasah/media/areaofwz7uzulda4p3m8.png"></p><p>Akibat sifat kikir yang sesuai dengan kandungan hadis diatas adalah!</p>',5,1,NULL,NULL,3,'["Saling toleransi antar sesama teman ","Saling memfitnah dan menjelek-jelekkan sesama","Pertumpahan darah dan menghalalkan segala sesuatu yang diharamkan","Dimurkai Allah dan di asingkan oleh teman"]','"D"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(259,13,'pilihan_ganda','<div>Ghina membaca al qur’an pada bacaan <img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237083/ujian-madrasah/media/cxhd8rkcpc386sgzpij8.png"> di baca panjang 3 alif,pada lafadz tersebut termasuk bacaan ….</div>',6,1,NULL,NULL,3,'["Mad jaiz munfasil","Mad wajib muttasil","Mad thabi’i","Mad iwad"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(260,13,'pilihan_ganda','<ol><li>Perhaikan tabel dibawah ini!</li></ol><table><tbody><tr><td><p>A</p></td><td><p>B</p></td><td><p>C</p></td><td><p>D</p></td></tr><tr><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237083/ujian-madrasah/media/ksblfyyi8qlthuqengur.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237084/ujian-madrasah/media/nr49qpn0puhxt6q4wclh.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237085/ujian-madrasah/media/hcfnxonvnb7lpu42hvhr.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237086/ujian-madrasah/media/ewjnnip8vulvx98ewm3r.png"></p></td></tr><tr><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237086/ujian-madrasah/media/qygt2n3ct2oob9thfchv.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237087/ujian-madrasah/media/ge0cxfqflqmfxxzhkcjw.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237088/ujian-madrasah/media/lox9g2k8ay9iubb4h1mn.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237088/ujian-madrasah/media/nxev6tzyxbvtmbpxksog.png"></p></td></tr><tr><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237089/ujian-madrasah/media/i3pgumirxskqxegbpcst.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237090/ujian-madrasah/media/ov8ebcvloe5itzmnpdsy.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237091/ujian-madrasah/media/eakcg3z3a8orrfvubkcl.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237091/ujian-madrasah/media/ranyb7myx6yoicxfda0p.png"></p></td></tr></tbody></table><p>Mengidentifikasi Lafadz yang termasuk hukum bacaan mad thabi’I dan mad wajib muttasil serta mad jaiz munfasil pada tabel diatas adalah.</p>',7,1,NULL,NULL,3,'["A dan B","B dan C","C dan D","D dan A"]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(261,13,'pilihan_ganda','<ol><li>Ali anak yang nakal karena faktor lingkungan dan teman-temannya, tetapi dia mempunyai keinginan untuk bertaubat agar menjadi orang yang baik, Dia memunyai mutivasi untuk selalu bersikap optimis terhadap ampunan dan rahmat dari allah swt.</li></ol><p>Pada pernyataan diatas termasuk kandungan al qur’an surah….</p>',8,1,NULL,NULL,3,'["Az zumar ayat 51","Az zumar ayat 52","Az zumar ayat 53","Az zumar ayat 54"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(262,13,'pilihan_ganda','<div>Allah swt, memberikan ujian dan jalan keluar bagi semua hambanya sikap kaum mukminin ketika mendapat kemudahan dari allah swt, adalah….</div>',9,1,NULL,NULL,3,'["Bersikap biasa saja","Tidak menerima kemudahan tersebut","Memanfaatkan kemudahan tersebut","Bersukur kepada allah swt."]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(263,13,'pilihan_ganda','<ol><li>Perhatikan pernyataan dibawah ini!</li></ol><p>“Ketika kita menghendaki pertolongan dari allah swt. Maka kita harus bersikap sabar.jalan keluar yang dihadapi ada bersama kesulian-kesulitan tersebut”</p><p>Pada pernyataan diatas termasuk kandungan hadis riwayat…</p>',10,1,NULL,NULL,3,'["HR At tirmidzi","HR Annasa’I ","HR Muslim","HR Bilal"]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(264,13,'pilihan_ganda','<ol><li>Perhatikan table berikut!</li></ol><table><tbody><tr><td><p>1</p></td><td><p>2</p></td><td><p>3</p></td><td><p>4</p></td></tr><tr><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237092/ujian-madrasah/media/etz3ybm4hmezwljx22a5.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237093/ujian-madrasah/media/alczz6wasmg0m6irlfvy.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237093/ujian-madrasah/media/ovsezcdj2arnmnguna4e.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237094/ujian-madrasah/media/hagkbv7sbatuxxake39z.png"></p></td></tr><tr><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237095/ujian-madrasah/media/cvoeoiadp6yynkwnoc6x.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237095/ujian-madrasah/media/qjpsea1j5chzpzmjk9jt.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237096/ujian-madrasah/media/zs1hoip3xwkzno6d5lef.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237097/ujian-madrasah/media/l7nrikhwhvfkwdqskx8b.png"></p></td></tr><tr><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237098/ujian-madrasah/media/ld508r5z0ssyrdivalgi.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237099/ujian-madrasah/media/w0fr1jircqajtrbq39re.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237099/ujian-madrasah/media/c6fx0smqttcsa8d3xke4.png"></p></td><td><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237100/ujian-madrasah/media/ohheqmunjcvr05nzzdsd.png"></p></td></tr></tbody></table><p>Lafadz bacaan mad iwad,mad arid lissukun serta mad layyin ditunjukkan pada kolom nomor….</p>',11,1,NULL,NULL,3,'["1 ,2, 3","1, 3, 2","1, 4, 2","1, 3, 4"]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(265,13,'pilihan_ganda','<ol><li>Perhatikan ayat di bawah ini!</li></ol><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237101/ujian-madrasah/media/fqrlvhjc8uzj9jtxqe7g.png"></p><p>Pada akhir ayat diatas hasan memanjangkan bacaannya, karena terdapat huruf wawu sukun yang didahului oleh huruf berharakat fathah dan setelahnya ada huruf hidup yang di wakafkan.hal tersebut dilakukan karena pada ayat terebut terdapat hokum bacaan  …</p>',12,1,NULL,NULL,3,'["Mad wajib muttasil","Mad layyin","Mad aridlissukun","Mad iwad"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(266,13,'pilihan_ganda','<div>Surah al baqarah ayat 254  menjelaskan perintah untuk menyedekahkan harta sesegera mungkin sebelum datangnya hari kiamat.pada ayat tersebut juga di jelaskan bahwa termasuk orang yang zalim,yaitu…</div>',13,1,NULL,NULL,3,'["Orang yang kikir","Orang yang durhaka","Orang kafir","Orang yang berdusta"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(267,13,'pilihan_ganda','<div>Surah al baqarah ayat 261  menjelaskan perumpamaan (nafkah yang dikeluarkan oleh) orang –orang yang menafkahkan hartanya dijalan Allah adalah serupa dengan sebutir benih yang menumbuhkan tujuh bulir, pada tiap-tiap bulir seratus biji. Allah melipat gandakan (ganjaran) bagi siapa yang dia kehendaki karena ...</div>',14,1,NULL,NULL,3,'["Mereka memperoleh pahala disisi Tuhan mereka","Tidak ada kekhawatiran terhadap mereka","Allah Maha luas (Karunia-Nya) lagi Maha mengetahui","Allah Maha kaya lagi Maha Penyantun"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(268,13,'pilihan_ganda','<ol><li>Perhatikan pernyataan dibawah ini!</li><li>Hakim anak yang dermawan, setiap hari dia menyisihkan uangnya untuk diberikan kepada teman kelasnya yang sudah tidak ada orang tuanya</li><li>Edo selalu meminta-minta kepada teman kelasnya karena uang jajannya selalu ditabung untuk kepeningan dirinya</li><li>Doni setiap hari meneraktir temannya makan, supaya temannya menyanjung dia.</li><li>Diki anak  yang demawan dia selalu memberi uang kepada tetangganya, tapi uang tersebut hasil mencuri.</li></ol><p>Dari pernyataan diatas manakah yang termasuk kandungan hadis riwayat bukhari dari hakim bin hizam.</p>',15,1,NULL,NULL,3,'["1","2","3","4"]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(269,13,'pilihan_ganda','<ol><li>Hasan orang yang kaya dia berprofesi sebagai menejer perusahan.setiap hari dia memberi nafkah kepada keluarganya, dan dia tidak lupa juga memberi sodaqah kepada tetangganya yang tidak mampu.</li></ol><p>Pada penyataan diatas termasuk kandungan hadis…</p>',16,1,NULL,NULL,3,'["HR.An nasa’I ","HR. Muslim","HR. Bukhari","HR. At tirmidzi"]','"C"','2026-08-09 00:58:38');
