INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(271,13,'pilihan_ganda','<ol><li>Perhatikan tabel berikut!</li></ol><table><tbody><tr><td></td><td><p>1</p></td><td><p>2</p></td><td><p>3</p></td><td><p>4</p></td></tr><tr><td><p>Istilah</p></td><td><p>Silah</p></td><td><p>Badal</p></td><td><p>Tamkin</p></td><td><p>farqi</p></td></tr><tr><td><p>Arti</p></td><td><p>Pengganti</p></td><td><p>Hubungan</p></td><td><p>Penetapan</p></td><td><p>Pembeda</p></td></tr></tbody></table><p>Yang istilah arti tidak sesuai adalah…</p>',18,1,NULL,NULL,3,'["1 dan 2","2 dan 3","3 dan 4","1 dan 4"]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(272,13,'pilihan_ganda','<ol><li>Perhatikan pernyataan berikut!</li></ol><p>  <img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237110/ujian-madrasah/media/rrhjheiuwcqfvqlfidt4.png"></p><ol><li>Riko membaca ayat  yang bergaris bawah di atas panjangnya 1 alif dua harokat                        </li><li>Amin membaca ayat  yang bergaris bawah di atas panjangnya dua harokat</li><li>Dimas membaca ayat  yang bergaris bawah di atas panjangnya 5 harokat</li><li>Karim membaca ayat  yang bergaris bawah di atas panjangnya 3 alif</li></ol><p>Diantara pernyataan-pernyataan di atas, yang benar tunjukkan pada nomor</p>',19,1,NULL,NULL,3,'["1 dan 2","3 dan 4","1 dan 3","2 dan 4"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(273,13,'pilihan_ganda','<ol><li>Sesuai kandungan qur’an surah Al A’la ayat 14-15,orang yang </li></ol><p>     beruntung dalah….</p>',20,1,NULL,NULL,3,'["Orang yang rajin bekerja","Orang beriman","Orang hemat","Orang yang menuntut ilmu"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(274,13,'pilihan_ganda','<ol><li><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237111/ujian-madrasah/media/zelqkfq3h8oul8mjdskn.png">Perhatikan ayat erikut ini!</li></ol><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237112/ujian-madrasah/media/anz19sgmavqzspa1cv2p.png"> </p><p>Orang yang beruntung sesuai ayat diatas adalah…</p>',21,1,NULL,NULL,3,'["Beriman, senantiasa mengingat allah swt, dan mengerjakan salat","Beriman, mengamalkan prilaku yang baik","Beriman, jarang melaksanakan erinah allah swt.","Beriman, sering beramal dan berbohong"]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(275,13,'pilihan_ganda','<ol><li>Perhatikan pernyataan dibawah ini!</li></ol><p>Manakah yang termasuk kandungan hadis riwayat muslim dari abu hurairah tentang hubungan kehidupan dunia dan akhirat.</p>',22,1,NULL,NULL,3,'["Manusia adalah mahluk yang lemah yang di tuntut untuk meminta dan bergantung hanya kepada allah swt, hanya allah tempat berkeluh kesah dari segala masalah. Hanya allah yang dapat memberikan solusi terhadap permasalahan tersebut.","Manusia adalah mahluk yang lemah yang dituntut untuk selalu meminta terhadap sesama mahluknya.karena manusia saling membutuhkan antara satu dengan yang lain","Manusia adalah mahluk yang sempurna dan saling membutuhkan antar sesama.","Manusia mahluk yang berakal ketika mempunyai permasalahan maka harus difikirkan sendiri tanpa meminta bantuan siapapun."]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(276,13,'pilihan_ganda','<ol><li>Perhatikan pengalan ayat berikut ini!</li></ol><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237112/ujian-madrasah/media/oo6851sqwbtiqs5x3tnu.png"></p><p>Dari lafal di atas manakah contoh bacaan mad lazim musaqol kilmi</p>',23,1,NULL,NULL,3,'["1","2","3","4"]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(277,13,'pilihan_ganda','<ol><li>Perhatikan ayat di awah ini</li></ol><p><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237113/ujian-madrasah/media/d1zvvkytxgvhdumo9vlz.png"> </p><p>Hukum bacaan pada kata yang bergaris bawah adalah…</p>',24,1,NULL,NULL,3,'["mad lazim mukhoffaf kilmi","mad lazim musaqqol kilmi","mad badal","mad lazim harfi musaqqol"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(278,13,'pilihan_ganda','<div>Dian membaca al qur’an surah thaha ayat pertama ketika membaca lafal thaha di baca  panjang 1 alif dua harakat karena berada di awal surah termasuk hukum bacaan…</div>',25,1,NULL,NULL,3,'["Mad lazim mukhaffaf kilmi","Mad lazim musaqqal kilmi","Mad lazim mukhaffaf harfi","Mad lazim musaqqal harfi"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(279,13,'pilihan_ganda','<ol><li>Perhatikan ayat di bawah ini!</li></ol><p> <img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237114/ujian-madrasah/media/bqsbfkmiuz4lllg40tmu.png"> </p><p>kandungan yang tepat pada penggalan ayat diatas adalah…</p>',26,1,NULL,NULL,3,'["larangan memakan harta anak yatim secara batil","perintah berbuat adil pada sahabat","perintah menyempurnakan takaran dan timbangan","perintah agar berkata dengan jujur"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(280,13,'pilihan_ganda','<ol><li>Perhaikan pernyataan-pernyataan berikut ini!</li><li>Larangan mendekati harta anak yatim dengan batil</li><li>Perintah menyempurnakan takaran dan timbangan</li><li>Larangan mendekati riba yang membinasakan</li><li>Perintah menjadi orang yang amanah dalam bermuamalah  </li><li>Perintah beraku adil terhadap siapapun meskipun terhadap kerabat dekat</li></ol><p>Kandungan surah al an’am ayat 152 ditunjukkan pada…</p>',27,1,NULL,NULL,3,'["1, 2, 3","1, 3, 4","1, 2, 5","1, 3, 5"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(281,13,'pilihan_ganda','<ol><li>Perhatikan pernyataan berikut ini!</li><li>Tinggalkanlah sesuatu yang meragukan, kepada sesuatu yang tidak meragukan dan kita harus berbuat adil</li><li>Ketika kita mendapatkan musibah harus sabar dan salat karena olat adalah tiang agama</li><li>Kita harus jujur dalam muamalah tidak boleh mengurangi timbangan</li><li>Ketika kita mendapatkan satukesulitan pasti ada kemudahan</li></ol><p>Diantara pernyataan hadis diatas,manakah yang termasuk kandungan hadis yang diriwayatkan oleh imam at tirmidzi dari hasan bin ali</p>',28,1,NULL,NULL,3,'["A","B","C","D"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(282,13,'pilihan_ganda','<div>Jujur dalam bermuamalah dapat di artikan sebagai kesesuaian antara pikiran, ucapan dan tindakan dalam berinteraksi sosial dengan sesama manusia di kehidupan sehari-hari, andi setiap hari berprofesi sebagai pedagang beras tapi ketika ada orang yang membeli dia selalu mengurangi takarannya,diko mengetahui tindakan andi tersebut lalu diko menegurnya.andi tidak meresponnya karna dia ingin mendapatkan hasil yang lebih banyak.tindakan yang sesuia yang harus lakukan yang berpedoman pada hadis riwayat at tirmidzi dari hasan bin ali adalah </div>',29,1,NULL,NULL,3,'["Mengajak pedagang supaya tidak curang dalam menakar.","Tidak merepon ajakan diko","Kita harus mementingkan diri kita sendiri","Harus bersikap adil."]','"A"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(283,13,'pilihan_ganda','<ol><li>Perhatikan kolom dibawah ini!</li></ol><table><tbody><tr><td><p>NO</p></td><td><p>KALIMAT</p></td><td><p>BACAAN</p></td></tr><tr><td><p>1</p></td><td><p><strong><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237115/ujian-madrasah/media/d6f1mbaki45dofvlmxrn.png"></strong></p></td><td><p>Naql</p></td></tr><tr><td><p>2</p></td><td><p><strong><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237115/ujian-madrasah/media/dszodhyhpwwyslgui2jw.png"></strong></p></td><td><p>isymam</p></td></tr><tr><td><p>3</p></td><td><p><strong><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237116/ujian-madrasah/media/yj7deuihmpabisuuwvc0.png"></strong></p></td><td><p>Imalah</p></td></tr><tr><td><p>4</p></td><td><p><strong><img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237117/ujian-madrasah/media/pmsgfynpauykua7m7dkg.png"></strong></p></td><td><p>tashil</p></td></tr></tbody></table><p>Pasangan yang tepat pada kolom diatas adalah….</p>',30,1,NULL,NULL,3,'["1","2","3","4"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(284,13,'pilihan_ganda','<div>Kirana anak yang solihah dia rajin mengaji di masjid bersama temannya,ketika dia membaca al qur’an kepada gurunya kirana ditegor  tepat pada ayat <img src="https://res.cloudinary.com/dfhtjgwcz/image/upload/v1786237118/ujian-madrasah/media/t0odv8lad9vmjuyhcsvc.png"> kirana membaca dengan bacaan yang kurang sesuai dengan kaidah ilmu tajwid.bagaimana cara yang tepat membaca ayat tersebut….</div>',31,1,NULL,NULL,3,'["Dengan cara mencucung kedua bibir","Dengan merubah mahorijul hurufnya","Dengan cara membaca huruf berharakat fathah yang dimiringkan ke kasrah","Dengan cara memasukkukkan bacaan lalu di idghomkan"]','"C"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(285,13,'pilihan_ganda','<ol><li>“Mengkombinasikan harakat fathah dengan harakar dommah disertai </li></ol><p>      monyong bibirnya “termasuk definisi dari….</p>',32,1,NULL,NULL,3,'["Imalah","Isymam","Tashil","Naql"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(286,13,'pilihan_ganda','<div>Zidan sering kali pergi ke majlis ilmu, ketika diperjalanan dia bertemu dengan temannya yang bernama dika lalu dia mengajaknya untuk bergabung di majlis tersebut,sesampainya dimajlis zidan dan dika duduk dengan tenang dan mengindahkan aturan majlis sambil mendengarkan kajian dari salah satu mubaligh,zidan dan dika memunyai keinginan ingin diangkat derajatnya oleh allah swt, prilaku yang dilakukan oleh zidan tersebut tercermin dalam al qur’an</div>',33,1,NULL,NULL,3,'["QS. Al Mujadalah (58):10","QS. Al Mujadalah (58):11","QS. Al Mujadalah (58):12","QS. Al Mujadalah (58):13"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(287,13,'pilihan_ganda','<div>Di bawah ini manakah yang termasuk kandungan hadis riwayat ibnu majah dari shofwan assal al muradi…</div>',34,1,NULL,NULL,3,'["Allah akan mengangkat derajat bagi rang yang berilmu","Malaikat akan mengepakkan sayapnya karena ridha terhadap prilakunya","Allah akan memeri jalan keluar bagi orang yang sholeh","Malaikat akan membimbing orang yang berilmu"]','"B"','2026-08-09 00:58:38');
INSERT INTO "questions" ("id","exam_id","type","question_text","question_number","points","media_type","media_url","audio_max_plays","options_json","correct_answer_json","created_at") VALUES(288,13,'pilihan_ganda','<div>Dalam hadis riwayat muslim dari abuhurairah, allah swt menjanjikan sesuatu terhadap orang yang menimba ilmu yaitu…</div>',35,1,NULL,NULL,3,'["Dimudahkan jalannya menuju surga","Dimudahkan hidupnya didunia dan ahirat","Dimudahkan mencari rizqi","Dimudahkan menggapai kebahagiaan"]','"A"','2026-08-09 00:58:38');
